```cpp
inline bool get_offsets (hb_codepoint_t  glyph,
                         unsigned int   *start_offset /* OUT */,
                         unsigned int   *end_offset   /* OUT */) const
{
  if (unlikely (glyph >= num_glyphs))
    return false;

  if (short_offset)
  {
    const HBUINT16 *offsets = (const HBUINT16 *) loca_table->dataZ;
    *start_offset = 2 * offsets[glyph];
    *end_offset   = 2 * offsets[glyph + 1];
  }
  else
  {
    const HBUINT32 *offsets = (const HBUINT32 *) loca_table->dataZ;
    *start_offset = offsets[glyph];
    *end_offset   = offsets[glyph + 1];
  }
  ...
}
```

`offsets[glyph + 1]` reads at index `glyph + 1`. Since `glyph < num_glyphs`, `glyph + 1 <= num_glyphs`. The loca table has `num_glyphs + 1` entries (since `num_glyphs = loca_len / entry_size - 1`). So `offsets[glyph + 1]` is within bounds.

